<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1 class="mb-4">Job Application</h1>

    @* ───── Step Indicator Bar ───── *@
    <nav class="step-indicator mb-4">
        @for (int i = 0; i < _stepNames.Length; i++)
        {
            var step = i + 1;
            var state = step < _currentStep ? "completed"
                      : step == _currentStep ? "active"
                      : "upcoming";
            <button class="step-item @state"
                    disabled="@(state == "upcoming")"
                    @onclick="() => GoToStep(step)">
                <span class="step-circle">
                    @if (state == "completed")
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@_stepNames[step - 1]</span>
            </button>

            @if (step < _stepNames.Length)
            {
                <span class="step-connector @state"></span>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (_currentStep == 1)
    {
        <section class="step-panel">
            <h3>Personal Information</h3>

            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="Jane Doe" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" placeholder="jane@example.com" />
                @if (_emailValidationMessage is not null)
                {
                    <div class="form-text text-danger">@_emailValidationMessage</div>
                }
            </div>

            <div class="mb-3">
