                <div class="review-section">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>References</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    @foreach (var refEntry in _references)
                    {
                        <div class="mb-2 ps-2 border-start border-3">
                            <strong>@refEntry.Name</strong> — @refEntry.Relationship<br />
                            <small class="text-muted">@refEntry.Email · @refEntry.Phone</small>
                        </div>
                    }
                </div>

                @* Cover Letter *@
                <div class="review-section">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>Cover Letter</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(4)">Edit</button>
                    </div>
                    <p class="mb-0" style="white-space: pre-wrap;">@_coverLetter</p>
                </div>

                <div class="step-actions">
                    <button class="btn btn-secondary" @onclick="() => GoToStep(4)">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isProcessing">
                        @if (_isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Submit Application
                    </button>
                </div>
            }
        </section>
    }
</div>

@code {
    private static readonly string[] _stepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep = 1;
    private int _highestCompletedStep = 0;
    private bool _isProcessing;
    private string? _errorMessage;

    // Step 1
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;
    private string? _emailValidationMessage;

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new()];

    // Step 4
    private string _coverLetter = string.Empty;

    // Step 5
    private bool _submitted;
    private int _submittedId;

    // ── Navigation ──

    private void GoToStep(int step)
    {
        if (step <= _highestCompletedStep + 1)
        {
            _currentStep = step;
            _errorMessage = null;
        }
    }

    private void AdvanceTo(int step)
    {
        _highestCompletedStep = Math.Max(_highestCompletedStep, step - 1);
        _currentStep = step;
        _errorMessage = null;
    }

    // ── Step 1 validation ──

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;
        _emailValidationMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isProcessing = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(_email);
            if (!valid)
            {
                _emailValidationMessage = "Please enter a valid email address.";
                _errorMessage = "Email validation failed.";
                return;
            }

            AdvanceTo(2);
        }
        finally
        {
            _isProcessing = false;
        }
    }

    // ── Step 2 ──

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void ToggleCurrent(WorkEntryModel entry, bool isCurrent)
    {
        entry.IsCurrent = isCurrent;
        if (isCurrent) entry.EndDate = null;
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = null;
        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate is null)
            {
                _errorMessage = "Each position must have a company name, job title, and start date.";
                return;
            }
        }
        AdvanceTo(3);
    }

    // ── Step 3 ──

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 1)
            _references.RemoveAt(index);
    }

    private void NextFromReferences()
    {
        _errorMessage = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please complete all fields for each reference.";
                return;
            }
        }
        AdvanceTo(4);
    }

    // ── Step 5: Submit ──

    private async Task SubmitApplication()
    {
        _isProcessing = true;
        _errorMessage = null;
        try
        {
            var application = BuildApplication();
            _submittedId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private JobApplication BuildApplication()
    {
        var personal = new PersonalInfo(_fullName, _email, _phone, _address);

        var workEntries = _workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description))
            .ToList();

        var refs = _references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone))
            .ToList();

        return new JobApplication(personal, new WorkHistory(workEntries), refs, _coverLetter);
    }

    // ── Mutable form models ──

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}
