{"file_text": ".apply-container {
    max-width: 800px;
    margin: 0 auto;
}

/* ── Step Indicator ── */

.step-indicator {
    display: flex;
    align-items: center;
    gap: 0;
    flex-wrap: wrap;
    padding: 1rem 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    padding: 0.25rem 0.5rem;
    cursor: pointer;
    flex-shrink: 0;
    transition: opacity 0.2s;
}

.step-item:disabled {
    cursor: default;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    margin-bottom: 0.35rem;
    transition: all 0.2s;
}

.step-label {
    font-size: 0.75rem;
    white-space: nowrap;
    font-weight: 500;
}

.step-connector {
    flex: 1;
    height: 2px;
    min-width: 16px;
    align-self: center;
    margin-bottom: 1.5rem;
    transition: background 0.2s;
}

/* States */
.step-item.completed .step-circle {
    background: #198754;
    color: #fff;
}
.step-item.completed .step-label {
    color: #198754;
}

.step-item.active .step-circle {
    background: #0d6efd;
    color: #fff;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.25);
}
.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 700;
}

.step-item.upcoming .step-circle {
    background: #e9ecef;
    color: #6c757d;
}
.step-item.upcoming .step-label {
    color: #adb5bd;
}

.step-connector.completed {
    background: #198754;
}
.step-connector.active {
    background: #0d6efd;
}
.step-connector.upcoming {
    background: #e9ecef;
}

/* ── Step Panel ── */

.step-panel {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-panel h3 {
    margin-bottom: 1.25rem;
    padding-bottom: 0.75rem;
    border-bottom: 2px solid #e9ecef;
}

.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e9ecef;
}

/* ── Review Section ── */

.review-section {
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-section h5 {
    margin-bottom: 0.5rem;
}
