@page "/apply"
@rendermode InteractiveServer
@using sv_c7c9ca77fe2a4929bba2a3829d8c9236.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1 class="mb-4">Job Application</h1>

    @* ───── Step Indicator Bar ───── *@
    <nav class="step-indicator mb-4">
        @for (int i = 0; i < _stepNames.Length; i++)
        {
            var step = i + 1;
            var state = step < _currentStep ? "completed"
                      : step == _currentStep ? "active"
                      : "upcoming";
            <button class="step-item @state"
                    disabled="@(state == "upcoming")"
                    @onclick="() => GoToStep(step)">
                <span class="step-circle">
                    @if (state == "completed")
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@_stepNames[step - 1]</span>
            </button>

            @if (step < _stepNames.Length)
            {
                <span class="step-connector @state"></span>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (_currentStep == 1)
    {
        <section class="step-panel">
            <h3>Personal Information</h3>

            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="Jane Doe" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" placeholder="jane@example.com" />
                @if (_emailValidationMessage is not null)
                {
                    <div class="form-text text-danger">@_emailValidationMessage</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
            </div>

            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <textarea class="form-control" rows="2" @bind="_address" placeholder="123 Main St, City, State ZIP"></textarea>
            </div>

            <div class="step-actions">
                <span></span>
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isProcessing">
                    @if (_isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Next
                </button>
            </div>
        </section>
    }

    @* ───── Step 2: Work History ───── *@
    else if (_currentStep == 2)
    {
        <section class="step-panel">
            <h3>Work History</h3>

            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                var entry = _workEntries[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Position @(index + 1)</h5>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>

                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Company <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Company"
                                       @onchange="e => entry.Company = e.Value?.ToString() ?? string.Empty" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => entry.Title = e.Value?.ToString() ?? string.Empty" />
                            </div>
                        </div>

                        <div class="row mb-2">
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" value="@entry.StartDate?.ToString("yyyy-MM-dd")"
                                       @onchange="e => entry.StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" disabled="@entry.IsCurrent"
                                       value="@entry.EndDate?.ToString("yyyy-MM-dd")"
                                       @onchange="e => entry.EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end mb-1">
                                <div class="form-check">
                                    <input type="checkbox" class="form-check-input" id="current-@index"
                                           checked="@entry.IsCurrent" @onchange="e => ToggleCurrent(entry, (bool)(e.Value ?? false))" />
                                    <label class="form-check-label" for="current-@index">Currently working here</label>
                                </div>
                            </div>
                        </div>

                        <div class="mb-2">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="3" value="@entry.Description"
                                      @onchange="e => entry.Description = e.Value?.ToString() ?? string.Empty"
                                      placeholder="Describe your responsibilities and achievements"></textarea>
                        </div>
                    </div>
                </div>
            }

            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">
                + Add Another Position
            </button>

            <div class="step-actions">
                <button class="btn btn-secondary" @onclick="() => GoToStep(1)">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </section>
    }

    @* ───── Step 3: References ───── *@
    else if (_currentStep == 3)
    {
        <section class="step-panel">
            <h3>References</h3>

            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                var refEntry = _references[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Reference @(index + 1)</h5>
                            @if (_references.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>

                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Name"
                                       @onchange="e => refEntry.Name = e.Value?.ToString() ?? string.Empty" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Relationship"
                                       @onchange="e => refEntry.Relationship = e.Value?.ToString() ?? string.Empty"
                                       placeholder="e.g., Former Manager" />
                            </div>
                        </div>

                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" value="@refEntry.Email"
                                       @onchange="e => refEntry.Email = e.Value?.ToString() ?? string.Empty" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" value="@refEntry.Phone"
                                       @onchange="e => refEntry.Phone = e.Value?.ToString() ?? string.Empty" />
                            </div>
                        </div>
                    </div>
                </div>
            }

            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                    + Add Reference
                </button>
            }

            <div class="step-actions">
                <button class="btn btn-secondary" @onclick="() => GoToStep(2)">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </section>
    }

    @* ───── Step 4: Cover Letter ───── *@
    else if (_currentStep == 4)
    {
        <section class="step-panel">
            <h3>Cover Letter</h3>

            <div class="mb-3">
                <textarea class="form-control" rows="12" maxlength="2000"
                          @bind="_coverLetter" @bind:event="oninput"
                          placeholder="Write your cover letter here..."></textarea>
                <div class="form-text text-end">
                    @(_coverLetter.Length) / 2000 characters
                </div>
            </div>

            <div class="step-actions">
                <button class="btn btn-secondary" @onclick="() => GoToStep(3)">Back</button>
                <button class="btn btn-primary" @onclick="() => AdvanceTo(5)">Next</button>
            </div>
        </section>
    }

    @* ───── Step 5: Review & Submit ───── *@
    else if (_currentStep == 5)
    {
        <section class="step-panel">
            <h3>Review &amp; Submit</h3>

            @if (_submitted)
            {
                <div class="alert alert-success text-center">
                    <h4 class="alert-heading">Application Submitted!</h4>
                    <p>Your application has been received. Your confirmation number is:</p>
                    <p class="display-6 fw-bold">#@_submittedId</p>
                </div>
            }
            else
            {
                @* Personal Info *@
                <div class="review-section">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>Personal Information</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>

                @* Work History *@
                <div class="review-section">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>Work History</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-2 ps-2 border-start border-3">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <small class="text-muted">
                                @entry.StartDate?.ToString("MMM yyyy") –
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                            </small>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0 mt-1">@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                @* References *@
                <div class="review-section">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>References</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    @foreach (var refEntry in _references)
                    {
                        <div class="mb-2 ps-2 border-start border-3">
                            <strong>@refEntry.Name</strong> — @refEntry.Relationship<br />
                            <small class="text-muted">@refEntry.Email · @refEntry.Phone</small>
                        </div>
                    }
                </div>

                @* Cover Letter *@
                <div class="review-section">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>Cover Letter</h5>
                        <button class="btn btn-link btn-sm" @onclick="() => GoToStep(4)">Edit</button>
                    </div>
                    <p class="mb-0" style="white-space: pre-wrap;">@_coverLetter</p>
                </div>

                <div class="step-actions">
                    <button class="btn btn-secondary" @onclick="() => GoToStep(4)">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isProcessing">
                        @if (_isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Submit Application
                    </button>
                </div>
            }
        </section>
    }
</div>

