        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate is null)
            {
                _errorMessage = "Each position must have a company name, job title, and start date.";
                return;
            }
        }
        AdvanceTo(3);
    }

    // ── Step 3 ──

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 1)
            _references.RemoveAt(index);
    }

    private void NextFromReferences()
    {
        _errorMessage = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please complete all fields for each reference.";
                return;
            }
        }
        AdvanceTo(4);
    }

    // ── Step 5: Submit ──

    private async Task SubmitApplication()
    {
        _isProcessing = true;
        _errorMessage = null;
        try
        {
            var application = BuildApplication();
            _submittedId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private JobApplication BuildApplication()
    {
        var personal = new PersonalInfo(_fullName, _email, _phone, _address);

        var workEntries = _workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description))
            .ToList();

        var refs = _references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone))
            .ToList();

        return new JobApplication(personal, new WorkHistory(workEntries), refs, _coverLetter);
    }

    // ── Mutable form models ──

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

.apply-container {
    max-width: 800px;
    margin: 0 auto;
}

/* ── Step Indicator ── */

.step-indicator {
    display: flex;
    align-items: center;
    gap: 0;
    flex-wrap: wrap;
    padding: 1rem 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    padding: 0.25rem 0.5rem;
    cursor: pointer;
    flex-shrink: 0;
    transition: opacity 0.2s;
}

.step-item:disabled {
    cursor: default;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    margin-bottom: 0.35rem;
    transition: all 0.2s;
}

.step-label {
    font-size: 0.75rem;
    white-space: nowrap;
    font-weight: 500;
}

.step-connector {
    flex: 1;
    height: 2px;
    min-width: 16px;
    align-self: center;
    margin-bottom: 1.5rem;
    transition: background 0.2s;
}

/* States */
.step-item.completed .step-circle {
    background: #198754;
    color: #fff;
}
.step-item.completed .step-label {
    color: #198754;
}

.step-item.active .step-circle {
    background: #0d6efd;
    color: #fff;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.25);
}
.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 700;
}

.step-item.upcoming .step-circle {
    background: #e9ecef;
    color: #6c757d;
}
.step-item.upcoming .step-label {
    color: #adb5bd;
}

.step-connector.completed {
    background: #198754;
}
.step-connector.active {
    background: #0d6efd;
}
.step-connector.upcoming {
    background: #e9ecef;
}

/* ── Step Panel ── */

.step-panel {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.step-panel h3 {
    margin-bottom: 1.25rem;
    padding-bottom: 0.75rem;
    border-bottom: 2px solid #e9ecef;
}

.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e9ecef;
}

/* ── Review Section ── */

.review-section {
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-section h5 {
    margin-bottom: 0.5rem;
}

